/**
  * @brief This function handles System tick timer.
  */
void SysTick_Handler(void)
{
  /* USER CODE BEGIN SysTick_IRQn 0 */

  /* USER CODE END SysTick_IRQn 0 */
  HAL_IncTick();
  /* USER CODE BEGIN SysTick_IRQn 1 */
  /* one PB13 edge per 1 ms tick. HAL_GPIO_TogglePin is a single BSRR
     write (no ODR read-modify-write), so it cannot clobber the main loop's
     PB14 toggle on the same port even if it interrupts it. */
  if (tick_out_enabled)
  {
    HAL_GPIO_TogglePin(TICK_OUT_GPIO_Port, TICK_OUT_Pin);
  }
  /* USER CODE END SysTick_IRQn 1 */
}

